import json,re
from pathlib import Path
b=Path('/tmp/consumer-views-results');rows=[]
for label in ['control','views','shorter']:
 for seed in [7,11,23]:
  p=b/f'{label}-{seed}.json'
  if not p.exists():continue
  d=json.loads(p.read_text())
  for batch,r in zip(d['batches'],d['result']['rounds']):
   rows.append(dict(run=p.stem,shift=batch['shift'],seconds=batch['seconds'],coverage=r['belief_metrics']['coverage'],brier=r['belief_metrics']['brier_score'],beliefs=r['beliefs'],score=d['result']['aggregate']['station_score'],regret=d['result']['aggregate']['regret'],aborts=batch['metrics']['search_aborts'],pops=batch['metrics']['agenda_pops']))
  if label=='control':
   old=json.load(open(f'/tmp/stationops-depth-results/control-{seed}.json'))
   norm=lambda x:re.sub(r'kb[0-9a-f]{32}','kbUUID',json.dumps(x))
   assert norm([x['answers'] for x in d['batches']])==norm([x['answers'] for x in old['batches']])
for r in rows:print(r['run'],r['shift'],round(r['seconds'],2),r['coverage'],round(r['brier'],6),r['score'],r['regret'],r['aborts'],r['pops'])
(b/'summary.json').write_text(json.dumps(rows,indent=2)+'\n')

