from pathlib import Path
import difflib,json,shutil,subprocess
root=Path('/nexus/Dev/OpenCog/NL2PLN_Project/PeTTaChainer');b=Path('/tmp/consumer-views-results');candidate=Path('/tmp/consumer-views');control=Path('/tmp/consumer-views-control')
patch=[]
for f in (b/'changed-files.txt').read_text().splitlines():
 new=(candidate/f).read_text();assert (root/f).read_text()==new,f
 old=(control/f).read_text() if (control/f).exists() else ''
 patch.extend(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='a/'+f if (control/f).exists() else '/dev/null',tofile='b/'+f))
(b/'consumer-views.patch').write_text(''.join(patch))
runs={}
for label in ['control','views','shorter']:
 for seed in [7,11,23]:
  name=f'{label}-{seed}';p=b/f'{name}.json'
  if not p.exists():continue
  d=json.loads(p.read_text());batches=[]
  for batch,r in zip(d['batches'],d['result']['rounds']):
   selected={k:v for k,v in batch.items() if k!='stores'}
   selected.update(belief_metrics=r['belief_metrics'],beliefs=r['beliefs'])
   if seed==7 and batch['shift']==2:
    needles=['ProblemDependency shift-02 M01','LocalProblem shift-02 M01','PressureAlarm old power-converter shift-02-M03']
    for space,rows in batch['stores'].items():
     if space!='goal_waiter':selected['relevant_'+space]=[s for s in rows if any(n in s for n in needles)]
   batches.append(selected)
  runs[name]=dict(environment=d['environment'],workload=d['workload'],batches=batches,events=d['events'],score=d['result']['aggregate']['station_score'],regret=d['result']['aggregate']['regret'])
meta={k:subprocess.check_output(cmd,cwd=root,text=True).strip() for k,cmd in {'baseline_revision':['git','rev-parse','c0cd54e3'],'branch':['git','branch','--show-current'],'master_revision':['git','rev-parse','master'],'petta_tree':['git','rev-parse','HEAD:third_party/petta'],'chainergame_revision':['git','-C','../../ChainerGame','rev-parse','HEAD']}.items()}
meta.update(fetch_or_rebuild=False,repetitions=1,order='Sequential seeds 7,11,23, views then control each; shorter seeds 7,11,23 separately afterward.',baseline_dirty='Only pre-existing untracked .claude/, baseline_agenda_incumbent.json, tmp.txt.',candidate='Included consumer-views.patch applied to c0cd54e3; actual experimental branch implementation matches candidate archive. Master unchanged.',shorter='Separate diagnostic, additionally applies shorter-path.patch; depth change is not in working runtime.',timing='Batch seconds measure query_many only. infer event also includes post-query proof snapshots. No timed episode overlaps CPU-heavy validation.',validation='Pinned runtime; scripts/test_metta.sh strict+strict-det, Python and ConceptNet repeated after final source-pool cleanup. Full verify including import scaling passed before that query-only cleanup.')
logs={p.name:p.read_text() for p in [b/'final-metta.log',b/'final-python.log',b/'final-conceptnet.log',b/'verify.log',b/'matrix.log',b/'shorter-focused.log']}
source={name:(b/name).read_text() for name in ['benchmark.py','run.py','analyze.py','consumer-views.patch','package.py']}
source['shorter-path.patch']=Path('/tmp/stationops-depth-results/shorter-path.patch').read_text()
payload=dict(metadata=meta,summary=json.loads((b/'summary.json').read_text()),runs=runs,source=source,logs=logs,python_metrics=[json.loads(line) for line in (b/'final-python-metrics.jsonl').read_text().splitlines()])
(root/'benchmarks/stationops/consumer-views-results-2026-09-09.json').write_text(json.dumps(payload,indent=2)+'\n')
out=root/'scratch/stationops-consumer-views-2026-09-09';out.mkdir(parents=True,exist_ok=True)
for p in b.iterdir():
 if p.is_file():shutil.copy2(p,out/p.name)
print('Packaged',list(runs))
